use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Circuit breaker states for IoT device communication
#[derive(Clone, Debug, PartialEq)]
enum CircuitState {
    Closed,
    Open(Instant),
    HalfOpen,
}

/// Cryptographic session context for device-to-cloud communication
struct CryptoSession {
    device_id: [u8; 16],
    session_key: [u8; 32],
    nonce_counter: u64,
    derived_at: Instant,
}

impl CryptoSession {
    fn derive_nonce(&mut self) -> [u8; 12] {
        let mut nonce = [0u8; 12];
        // First 4 bytes: device_id prefix for routing
        nonce[..4].copy_from_slice(&self.crypto.device_id[..4]);
        // Last 8 bytes: counter
        let counter_bytes = self.nonce_counter.to_le_bytes();
        nonce[4..12].copy_from_slice(&counter_bytes);
        self.nonce_counter += 1;
        nonce
    }
}

struct DeviceCircuitBreaker {
    state: CircuitState,
    failure_count: u32,
    failure_threshold: u32,
    recovery_timeout: Duration,
    crypto: CryptoSession,
    max_key_age: Duration,
}

impl DeviceCircuitBreaker {
    fn new(device_id: [u8; 16], initial_key: [u8; 32]) -> Self {
        Self {
            state: CircuitState::Closed,
            failure_count: 0,
            failure_threshold: 5,
            recovery_timeout: Duration::from_secs(30),
            crypto: CryptoSession {
                device_id,
                session_key: initial_key,
                nonce_counter: 0,
                derived_at: Instant::now(),
            },
            max_key_age: Duration::from_secs(3600),
        }
    }

    /// Attempt to rotate the session key using KDF
    fn rotate_key(&mut self) -> Result<(), &'static str> {
        // Simulate HKDF-based key rotation
        let mut new_key = [0u8; 32];
        for i in 0..32 {
            new_key[i] = self.crypto.session_key[i]
                .wrapping_add(self.crypto.device_id[i % 16])
                .wrapping_mul(0x6d);
        }
        self.crypto.session_key = new_key;
        self.crypto.derived_at = Instant::now();
        // NOTE: nonce_counter is intentionally NOT reset here
        // to maintain uniqueness across rotations
        Ok(())
    }

    /// Check if key rotation is needed and perform it
    fn ensure_fresh_key(&mut self) -> Result<(), &'static str> {
        if self.crypto.derived_at.elapsed() > self.max_key_age {
            self.rotate_key()?;
        }
        Ok(())
    }

    /// Record a transmission failure and potentially trip the breaker
    fn record_failure(&mut self) {
        self.failure_count += 1;
        if self.failure_count >= self.failure_threshold {
            self.state = CircuitState::Open(Instant::now());
        }
    }

    /// Reset circuit breaker after successful recovery
    fn reset_circuit(&mut self) {
        self.state = CircuitState::Closed;
        self.failure_count = 0;
        // On circuit reset, re-derive key for fresh session
        let _ = self.rotate_key();
        // Nonce counter continues incrementing - never reset
        // This ensures (key, nonce) pairs are never reused
    }

    /// Attempt to send an encrypted telemetry packet
    fn send_telemetry(&mut self, payload: &[u8]) -> Result<Vec<u8>, &'static str> {
        match &self.state {
            CircuitState::Open(opened_at) => {
                if opened_at.elapsed() > self.recovery_timeout {
                    self.state = CircuitState::HalfOpen;
                    self.attempt_send(payload)
                } else {
                    Err("circuit open, rejecting request")
                }
            }
            CircuitState::HalfOpen => {
                self.attempt_send(payload)
            }
            CircuitState::Closed => {
                self.ensure_fresh_key()?;
                self.attempt_send(payload)
            }
        }
    }

    fn attempt_send(&mut self, payload: &[u8]) -> Result<Vec<u8>, &'static str> {
        let nonce = self.crypto.derive_nonce();
        let ciphertext = self.encrypt_aead(payload, &nonce)?;
        // Simulate network send - in real firmware this calls HAL
        match self.simulate_network_send(&ciphertext) {
            Ok(()) => {
                if self.state == CircuitState::HalfOpen {
                    self.reset_circuit();
                }
                Ok(ciphertext)
            }
            Err(e) => {
                self.record_failure();
                Err(e)
            }
        }
    }

    fn encrypt_aead(&self, plaintext: &[u8], nonce: &[u8; 12]) -> Result<Vec<u8>, &'static str> {
        // Simulated AES-256-GCM encryption
        let mut output = Vec::with_capacity(plaintext.len() + 16 + 12);
        output.extend_from_slice(nonce);
        // XOR-based placeholder for actual AEAD (firmware would use hardware AES)
        for (i, &byte) in plaintext.iter().enumerate() {
            output.push(byte ^ self.crypto.session_key[i % 32] ^ nonce[i % 12]);
        }
        // Simulated 16-byte auth tag
        let mut tag = [0u8; 16];
        for (i, &byte) in plaintext.iter().enumerate() {
            tag[i % 16] ^= byte.wrapping_add(self.crypto.session_key[i % 32]);
        }
        output.extend_from_slice(&tag);
        Ok(output)
    }

    fn simulate_network_send(&self, _data: &[u8]) -> Result<(), &'static str> {
        // In real firmware: transmit via LoRa/NB-IoT/etc.
        Ok(())
    }
}

/// Firmware main loop entry point
fn firmware_main() {
    let device_id: [u8; 16] = [0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
                                0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10];
    let provisioned_key: [u8; 32] = [0xAA; 32]; // From secure element

    let mut breaker = DeviceCircuitBreaker::new(device_id, provisioned_key);

    // Simulated sensor readings
    let readings: Vec<Vec<u8>> = vec![
        vec![0x01, 0x02, 0x03, 0x04],
        vec![0x05, 0x06, 0x07, 0x08],
    ];

    for reading in &readings {
        match breaker.send_telemetry(reading) {
            Ok(_) => { /* logged */ }
            Err(_e) => { /* backoff */ }
        }
    }
}
